import Home from "./pages/Home";
import Services from "./pages/Services";
import About from "./pages/About";
import Team from "./pages/Team";
import Gallery from "./pages/Gallery";

function App() {
  return (
    <>
      <Home />
      <Services />
      <About />
      <Team />
      <Gallery />
    </>
  );
}

export default App;
